use ratatui::{
    layout::{Alignment, Rect},
    text::{Line, Span},
    widgets::{Block, Borders, Paragraph},
    Frame,
};

use crate::theme::Theme;
use crate::AppState;
use game_core::GameState;

/// Active screen in the application
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Screen {
    #[default]
    Menu,
    EmpireSelect,
    NewGameSetup,
    SectorOverview,
    SectorMap,
    System,
    Colony,
    EmpireOverview,
    Research,
    Diplomacy,
    ShipDesigner,
    Settings,
}

impl Screen {
    /// Render this screen
    pub fn render(
        &self,
        frame: &mut Frame,
        area: Rect,
        app_state: &AppState,
        game_state: Option<&GameState>,
    ) {
        match self {
            Screen::Menu => menu::render_menu(frame, area, app_state),
            Screen::EmpireSelect => empire_select::render_empire_select(frame, area, app_state),
            Screen::NewGameSetup => new_game_setup::render_new_game_setup(frame, area, app_state),
            Screen::SectorOverview => {
                if let Some(state) = game_state {
