    let separator = Span::styled("  │  ", Theme::dim_border_style());
    let separator_width = separator.width();
    let mut current_spans: Vec<Span<'static>> = Vec::new();
    let mut current_width = 0usize;

    for (index, (key, desc)) in hints.iter().enumerate() {
