    11	
    12	/// Linear interpolation between two RGB colors.
    13	pub fn lerp_rgb(a: Color, b: Color, t: f32) -> Color {
    14	    let t = t.clamp(0.0, 1.0);
    15	    match (rgb_components(a), rgb_components(b)) {
    16	        (Some((ar, ag, ab)), Some((br, bg, bb))) => Color::Rgb(
    17	            (ar as f32 + (br as f32 - ar as f32) * t).round() as u8,
    18	            (ag as f32 + (bg as f32 - ag as f32) * t).round() as u8,
    19	            (ab as f32 + (bb as f32 - ab as f32) * t).round() as u8,
    20	        ),
    21	        _ if t < 0.5 => a,
    22	        _ => b,
    23	    }
    24	}
    25	
    26	/// Build an RGB gradient ramp. Non-RGB colors degrade to endpoint selection.
    27	pub fn gradient(a: Color, b: Color, steps: usize) -> Vec<Color> {
    28	    match steps {
    29	        0 => Vec::new(),
    30	        1 => vec![a],
    31	        _ => (0..steps)
    32	            .map(|index| {
    33	                let t = index as f32 / (steps.saturating_sub(1)) as f32;
    34	                lerp_rgb(a, b, t)
    35	            })
    36	            .collect(),
    37	    }
    38	}
