fn build_layout(main_area: Rect) -> SplashLayout {
    let dashboard_width = main_area.width.saturating_sub(6).clamp(74, 116);
    let dashboard_height = main_area.height.saturating_sub(2).clamp(19, 29);
    let x = main_area.x + (main_area.width.saturating_sub(dashboard_width)) / 2;
    let y = main_area.y + (main_area.height.saturating_sub(dashboard_height)) / 2;
    let dashboard = Rect::new(x, y, dashboard_width, dashboard_height);
    let inner = Rect::new(
        dashboard.x.saturating_add(2),
        dashboard.y.saturating_add(1),
        dashboard.width.saturating_sub(4),
        dashboard.height.saturating_sub(2),
    );
    let vertical = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(if dashboard.width >= WIDE_TITLE_WIDTH {
                8
            } else {
                5
            }),
            Constraint::Fill(1),
            Constraint::Length(4),
        ])
        .split(inner);
    let middle = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(67), Constraint::Percentage(33)])
        .split(vertical[1]);
    SplashLayout {
        dashboard,
        title: vertical[0],
        left: middle[0],
        right: middle[1],
        callout: vertical[2],
    }
}

