fn render_gradient_frame(frame: &mut Frame, area: Rect, palette: SplashPalette) {
    if area.width < 2 || area.height < 2 {
        return;
    }

    let top_gradient = gradient(palette.border_cold, palette.border_hot, area.width as usize);
    let side_gradient = gradient(
        palette.border_cold,
        palette.border_hot,
        area.height as usize,
    );
    let buffer = frame.buffer_mut();

    for x in 0..area.width {
        let glyph = match x {
            0 => '╭',
            value if value == area.width.saturating_sub(1) => '╮',
            _ => '─',
        };
        if let Some(cell) = buffer.cell_mut((area.x + x, area.y)) {
            cell.set_char(glyph);
            cell.set_style(
                Style::default()
                    .fg(top_gradient[x as usize])
                    .bg(palette.void_bg)
                    .add_modifier(Modifier::BOLD),
            );
        }
        if let Some(cell) = buffer.cell_mut((area.x + x, area.bottom().saturating_sub(1))) {
            let bottom_glyph = match x {
                0 => '╰',
                value if value == area.width.saturating_sub(1) => '╯',
                _ => '─',
            };
            cell.set_char(bottom_glyph);
            cell.set_style(
                Style::default()
                    .fg(top_gradient[area.width.saturating_sub(1) as usize - x as usize])
                    .bg(palette.void_bg)
                    .add_modifier(Modifier::BOLD),
            );
        }
    }

    for y in 1..area.height.saturating_sub(1) {
        let color = side_gradient[y as usize];
        if let Some(cell) = buffer.cell_mut((area.x, area.y + y)) {
            cell.set_char('│');
            cell.set_style(
                Style::default()
                    .fg(color)
                    .bg(palette.void_bg)
                    .add_modifier(Modifier::BOLD),
            );
        }
        if let Some(cell) = buffer.cell_mut((area.right().saturating_sub(1), area.y + y)) {
            cell.set_char('│');
            cell.set_style(
                Style::default()
                    .fg(color)
                    .bg(palette.void_bg)
                    .add_modifier(Modifier::BOLD),
            );
        }
    }
}

fn render_menu_starfield(
    frame: &mut Frame,
    area: Rect,
    app_state: &AppState,
    palette: SplashPalette,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }

    let mut canvas = Canvas::new(area.width, area.height);
    let detail = starfield_detail(area);
    let frame_group = if app_state.reduced_motion {
        0
    } else {
        app_state.tick_count / 6
    };

    for y in 0..area.height {
        for x in 0..area.width {
            let base_hash = visual_hash(0, x, y, 0, MENU_STARFIELD_SALT);
            let nebula_hash = visual_hash(0, x, y, frame_group, MENU_STARFIELD_SALT ^ 0xA5);
            let drift = (nebula_hash % 100) as f32 / 100.0;
            let depth = (base_hash % 100) as f32 / 100.0;
            let bg_color = lerp_rgb(
                lerp_rgb(palette.void_bg, palette.nebula_a, depth * 0.35),
                palette.nebula_b,
                drift * 0.2,
            );
            let mut symbol = ' ';
            let mut style = Style::default().bg(bg_color);

            let dust = base_hash % 97;
            if dust < 2 {
                symbol = '▓';
                style = style.fg(lerp_rgb(palette.nebula_b, palette.title_secondary, 0.25));
            } else if dust < 5 {
                symbol = '▒';
                style = style.fg(lerp_rgb(palette.nebula_a, palette.title_primary, 0.2));
            } else if dust < 11 {
                symbol = '░';
                style = style.fg(lerp_rgb(palette.nebula_a, palette.text_muted, 0.12));
            } else if dust == 12 {
                symbol = '·';
                style = style.fg(palette.text_muted);
            }

            if should_render_star(base_hash, detail) {
                let twinkle_hash = visual_hash(
                    0,
                    x,
                    y,
                    frame_group,
                    MENU_STARFIELD_SALT ^ MENU_STARFIELD_TWINKLE_SALT_XOR,
                );
                symbol = match twinkle_hash % 5 {
                    0 => '✦',
                    1 => '✧',
                    _ => detail_star_glyph(base_hash, detail),
                };
                let sparkle = 0.55 + (twinkle_hash % 45) as f32 / 100.0;
                style = Style::default().bg(bg_color).fg(lerp_rgb(
                    palette.title_primary,
                    palette.star_core,
                    sparkle,
                ));
            }

            canvas.set_cell(x, y, symbol, style, 0);
        }
    }

    canvas.render_to_buffer(area, frame.buffer_mut());
}

