    let emblem = EmpireEmblemPreview::from_palette(palette);
    let lines = vec![
        Line::from(Span::styled(
            "SIGNAL GLYPH",
            Style::default()
                .fg(palette.text_muted)
                .add_modifier(Modifier::BOLD),
        )),
        Line::from(""),
        Line::from(vec![
            Span::styled("   ◈", Style::default().fg(emblem.accent)),
            Span::styled(
                "╱╲",
                Style::default()
                    .fg(emblem.primary)
                    .add_modifier(Modifier::BOLD),
            ),
            Span::styled("◈", Style::default().fg(emblem.accent)),
        ]),
        Line::from(Span::styled(
            "   ╲██╱",
            Style::default()
                .fg(emblem.secondary)
                .add_modifier(Modifier::BOLD),
        )),
        Line::from(Span::styled(
            "   ╱██╲",
            Style::default()
                .fg(emblem.primary)
                .add_modifier(Modifier::BOLD),
        )),
        Line::from(vec![
