#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MenuAction {
    NewGame,
    LoadGame,
    Options,
    Quit,
}

impl MenuAction {
    pub const fn from_cursor(cursor: usize) -> Self {
        match cursor % MENU_ACTION_COUNT {
            0 => Self::NewGame,
            1 => Self::LoadGame,
            2 => Self::Options,
            _ => Self::Quit,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::NewGame => "New Game",
            Self::LoadGame => "Load Game",
            Self::Options => "Options",
            Self::Quit => "Quit",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SplashLayout {
    frame: Rect,
    title: Rect,
    menu: Rect,
    emblem: Rect,
    footer: Rect,
}

pub const fn menu_action_count() -> usize {
    MENU_ACTION_COUNT
}

fn build_layout(main_area: Rect) -> SplashLayout {
    let frame_width = main_area.width.saturating_sub(8).clamp(64, 92);
    let frame_height = main_area.height.saturating_sub(2).clamp(18, 28);
    let frame_x = main_area.x + (main_area.width.saturating_sub(frame_width)) / 2;
    let frame_y = main_area.y + (main_area.height.saturating_sub(frame_height)) / 2;
    let frame = Rect::new(frame_x, frame_y, frame_width, frame_height);
    let inner = Rect::new(
        frame.x.saturating_add(3),
        frame.y.saturating_add(1),
        frame.width.saturating_sub(6),
        frame.height.saturating_sub(2),
    );
    let sections = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(if frame.width >= WIDE_TITLE_WIDTH {
                9
            } else {
                6
            }),
            Constraint::Length(6),
            Constraint::Length(6),
            Constraint::Length(2),
        ])
        .split(inner);

    SplashLayout {
        frame,
        title: sections[0],
        menu: sections[1],
        emblem: sections[2],
        footer: sections[3],
    }
}

fn build_title_lines(area_width: u16, palette: SplashPalette) -> Vec<Line<'static>> {
    if area_width >= WIDE_TITLE_WIDTH {
        let colors = gradient(
            palette.title_primary,
            palette.title_secondary,
            TITLE_LINES_WIDE.len(),
        );
        let mut lines = TITLE_LINES_WIDE
            .iter()
            .enumerate()
            .map(|(index, line)| {
                Line::from(Span::styled(
                    (*line).to_string(),
                    Style::default()
                        .fg(colors[index])
                        .add_modifier(Modifier::BOLD),
                ))
            })
            .collect::<Vec<_>>();
        lines.push(Line::from(""));
        lines.push(Line::from(Span::styled(
            TAGLINE,
            Style::default()
                .fg(palette.accent)
                .add_modifier(Modifier::BOLD),
        )));
        lines
    } else {
        vec![
            Line::from(Span::styled(
                "FARSPACE",
                Style::default()
                    .fg(palette.title_primary)
                    .add_modifier(Modifier::BOLD),
            )),
            Line::from(Span::styled(
                TAGLINE,
                Style::default()
                    .fg(palette.accent)
                    .add_modifier(Modifier::BOLD),
            )),
        ]
    }
}

fn build_menu_lines(app_state: &AppState, palette: SplashPalette) -> Vec<Line<'static>> {
    (0..MENU_ACTION_COUNT)
        .map(|index| {
            let action = MenuAction::from_cursor(index);
            let selected = app_state.menu_cursor % MENU_ACTION_COUNT == index;
            let marker = if selected { "▶ " } else { "  " };
            let marker_style = if selected {
                Style::default()
                    .fg(palette.accent)
                    .bg(lerp_rgb(palette.void_bg, palette.nebula_b, 0.18))
                    .add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(palette.text_muted)
            };
            let label_style = if selected {
                Style::default()
                    .fg(palette.title_primary)
                    .bg(lerp_rgb(palette.void_bg, palette.nebula_b, 0.18))
                    .add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(Theme::fg())
            };

            Line::from(vec![
                Span::styled(marker.to_string(), marker_style),
                Span::styled(action.label().to_string(), label_style),
            ])
        })
        .collect()
}

