            let drift_hash = visual_hash(0, x, y, frame_group, MENU_STARFIELD_SALT ^ 0xA5);
            let drift = (drift_hash % 100) as f32 / 100.0;
            let depth = (base_hash % 100) as f32 / 100.0;
            let bg_color = lerp_rgb(
                lerp_rgb(palette.void_bg, palette.nebula_a, depth * 0.12),
                palette.nebula_b,
                drift * 0.05,
            );

            let mut symbol = ' ';
            let mut style = Style::default().bg(bg_color);
            let haze = base_hash % 257;

            if haze == 0 {
                symbol = '░';
                style = style.fg(lerp_rgb(palette.nebula_b, palette.title_secondary, 0.12));
            } else if haze < 3 {
                symbol = '·';
                style = style.fg(lerp_rgb(palette.nebula_a, palette.text_muted, 0.18));
            }

            if should_render_star(base_hash, detail) && base_hash.is_multiple_of(5) {
                let twinkle_hash = visual_hash(
                    0,
                    x,
                    y,
                    frame_group,
                    MENU_STARFIELD_SALT ^ MENU_STARFIELD_TWINKLE_SALT_XOR,
                );
                symbol = if twinkle_hash.is_multiple_of(9) {
                    '✦'
                } else {
                    detail_star_glyph(base_hash, detail)
                };
                let sparkle = 0.5 + (twinkle_hash % 20) as f32 / 100.0;
                style = Style::default().bg(bg_color).fg(lerp_rgb(
                    palette.title_primary,
                    palette.star_core,
                    sparkle,
                ));
            }

            canvas.set_cell(x, y, symbol, style, 0);
        }
    }

    canvas.render_to_buffer(area, frame.buffer_mut());
}

fn render_signal_glyph(frame: &mut Frame, area: Rect, palette: SplashPalette) {
    let emblem = EmpireEmblemPreview::from_palette(palette);
    let lines = vec![
        Line::from(Span::styled(
            "SIGNAL GLYPH",
            Style::default()
                .fg(palette.text_muted)
                .add_modifier(Modifier::BOLD),
        )),
        Line::from(""),
        Line::from(vec![
            Span::styled("   ◈", Style::default().fg(emblem.accent)),
            Span::styled(
                "╱╲",
                Style::default()
                    .fg(emblem.primary)
                    .add_modifier(Modifier::BOLD),
            ),
            Span::styled("◈", Style::default().fg(emblem.accent)),
        ]),
        Line::from(Span::styled(
            "   ╲██╱",
            Style::default()
                .fg(emblem.secondary)
                .add_modifier(Modifier::BOLD),
        )),
        Line::from(Span::styled(
            "   ╱██╲",
            Style::default()
                .fg(emblem.primary)
                .add_modifier(Modifier::BOLD),
        )),
        Line::from(vec![
            Span::styled("   ◈", Style::default().fg(emblem.accent)),
            Span::styled(
                "╲╱",
                Style::default()
                    .fg(emblem.secondary)
                    .add_modifier(Modifier::BOLD),
            ),
            Span::styled("◈", Style::default().fg(emblem.accent)),
        ]),
    ];

    let glyph = Paragraph::new(lines)
        .alignment(Alignment::Center)
        .style(Style::default().bg(palette.void_bg));
    frame.render_widget(glyph, area);
}

fn render_footer_line(frame: &mut Frame, area: Rect, palette: SplashPalette) {
    let footer = Paragraph::new(Line::from(Span::styled(
        FOOTER_HINT,
        Style::default().fg(palette.text_muted),
    )))
    .alignment(Alignment::Center)
    .style(Style::default().bg(palette.void_bg));
    frame.render_widget(footer, area);
}

fn render_compact_menu(
    frame: &mut Frame,
    area: Rect,
    app_state: &AppState,
    palette: SplashPalette,
) {
    let content = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(2),
            Constraint::Length(1),
            Constraint::Length(4),
            Constraint::Length(1),
        ])
        .split(Rect::new(
            area.x + area.width.saturating_sub(34) / 2,
            area.y + area.height.saturating_sub(10) / 2,
            area.width.min(34),
            area.height.min(10),
        ));

    frame.render_widget(
        Clear,
        Rect::new(content[0].x, content[0].y, content[0].width, 10),
    );
    frame.render_widget(
        Paragraph::new(vec![
            Line::from(Span::styled(
                "FARSPACE",
                Style::default()
                    .fg(palette.title_primary)
                    .add_modifier(Modifier::BOLD),
            )),
            Line::from(Span::styled(
                TAGLINE,
                Style::default()
                    .fg(palette.accent)
                    .add_modifier(Modifier::BOLD),
            )),
        ])
        .alignment(Alignment::Center)
        .style(Style::default().bg(palette.void_bg)),
        content[0],
    );
    frame.render_widget(
        Paragraph::new(build_menu_lines(app_state, palette))
            .alignment(Alignment::Left)
            .style(Style::default().bg(palette.void_bg)),
        content[2],
    );
    render_footer_line(frame, content[3], palette);
}

fn render_dashboard(frame: &mut Frame, area: Rect, app_state: &AppState, palette: SplashPalette) {
    let layout = build_layout(area);
    frame.render_widget(
        Block::default().style(Style::default().bg(palette.void_bg)),
        layout.frame,
    );
    render_gradient_frame(frame, layout.frame, palette);

    let title = Paragraph::new(build_title_lines(layout.frame.width, palette))
        .alignment(Alignment::Center)
        .style(Style::default().bg(palette.void_bg))
        .wrap(Wrap { trim: false });
    frame.render_widget(title, layout.title);

    let menu = Paragraph::new(build_menu_lines(app_state, palette))
        .alignment(Alignment::Left)
        .style(Style::default().bg(palette.void_bg));
    frame.render_widget(menu, layout.menu);

    render_signal_glyph(frame, layout.emblem, palette);
    render_footer_line(frame, layout.footer, palette);

    let version_area = Rect::new(
        layout.frame.right().saturating_sub(18),
        layout.frame.bottom().saturating_sub(2),
        16,
        1,
    );
    frame.render_widget(
        Paragraph::new(Span::styled(
            build_info(),
            Style::default().fg(palette.text_muted),
        ))
        .alignment(Alignment::Right)
        .style(Style::default().bg(palette.void_bg)),
        version_area,
    );
}

fn build_info() -> String {
    match option_env!("FARSPACE_BUILD_TAG") {
        Some(tag) if !tag.is_empty() => format!("v{}-{tag}", env!("CARGO_PKG_VERSION")),
        _ => format!("v{}", env!("CARGO_PKG_VERSION")),
    }
}

/// Render the main menu
pub fn render_menu(frame: &mut Frame, area: Rect, app_state: &AppState) {
    let (_header_area, main_area, _footer_area) = compose_layout(area);
    let palette = Theme::splash_palette();

    render_menu_starfield(frame, main_area, app_state, palette);

    if main_area.width < MIN_SPLASH_WIDTH || main_area.height < MIN_SPLASH_HEIGHT {
        render_compact_menu(frame, main_area, app_state, palette);
    } else {
        render_dashboard(frame, main_area, app_state, palette);
    }
}

